#include "ksStateAuditionTask.h"
#include <iostream>
#include <stdexcept>
using T=ks::StateAuditionTask;void check(bool b,const char* w){if(!b)throw std::runtime_error(w);}
int main(){try{uint64_t cases=0;for(unsigned state=0;state<256;++state){T task;unsigned clocks=0,polls=0,configs=0;while(!task.complete()&&!task.awaitingNote()){if(task.awaitingPoll()){++polls;check(task.resumePoll(uint8_t(state)),"Audition pollresume");continue;}if(task.awaitingConfigure()){++configs;check(task.mode()==(state==32?1:2)&&task.resumeConfigure(),"Audition configresume");continue;}auto c=task.nextClocks();check(!task.advanceBefore(c-1),"Audition earlyboundary");check(task.advanceBefore(c)==c,"Audition admission");clocks+=c;}bool on=state==32,off=state==16;check(polls==1&&configs==unsigned(on||off)&&task.event()==(on?T::Event::On:off?T::Event::Off:T::Event::None)&&clocks==(on?72:off?78:49),"Audition branch/clocks");if(on||off)check(task.note()==60&&task.velocity()==(on?127:64)&&task.retireNote(),"Audition noteevent");check(task.complete()&&!task.resumePoll(32)&&!task.resumeConfigure()&&!task.retireNote(),"Audition lifecycle");++cases;}std::cout<<"PASS: "<<cases<<" complete audition jobs/allstatusbytes/typedDSPmode+noteevents/deadlines+clocks\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
